type agreementSeparateNamespaceHeadingSourceReading struct {
	Cut         agreementRemovedCommentDiagnosticReading
	Projected   string
	Positions   []int
	Plain, Page agreementMixedNamespaceReading
	Native      agreementNativeHeadingSource
	IDs         []string
	Valid       bool
}

func agreementSeparateNamespaceHeadingRead(body string) agreementSeparateNamespaceHeadingSourceReading {
	r := agreementSeparateNamespaceHeadingSourceReading{Cut: agreementCommentCutP0Reading(body)}
	if !utf8.ValidString(body) {
		return r
	}
	source, positions := r.Cut.Projected, r.Cut.Positions
	if len(r.Cut.Check.Comments) == 0 {
		source = body
		positions = make([]int, len(body))
		for i := range positions {
			positions[i] = i
		}
	} else if !r.Cut.Valid {
		return r
	}
	if len(source) != len(positions) {
		return r
	}
	var projected strings.Builder
	for at, c := range source {
		size := utf8.RuneLen(c)
		if strings.ContainsRune(agreementNeutralHeadingRunes, c) {
			continue
		}
		if size < 1 || at+size > len(source) {
			return r
		}
		projected.WriteString(source[at : at+size])
		r.Positions = append(r.Positions, positions[at:at+size]...)
	}
	r.Projected = projected.String()
	for i, at := range r.Positions {
		if at < 0 || at >= len(body) || body[at] != r.Projected[i] || (i > 0 && at <= r.Positions[i-1]) {
			return r
		}
	}
	r.Plain = agreementMixedNamespaceRead(r.Projected, agreementFootnoteGrammar)
	r.Page = agreementMixedNamespaceRead(r.Projected, agreementExclusiveCodeGrammar)
	if !r.Plain.Eligible || !r.Page.Eligible || cmp.Equal(r.Plain, r.Page) {
		return r
	}
	r.IDs = agreementProseNeutralAllocate(r.Page.Bases)
	r.Native = agreementNativeHeadingReading(body)
	if !slices.Equal(r.Native.Check.Targets, judge.LinkTargets(body)) {
		return r
	}
	r.Valid = true
	return r
}

