type agreementSeparateNamespaceHeadingSource struct {
	Original, PrivateReading    agreementSeparateNamespaceHeadingSourceReading
	Native, PrivateNative       agreementNativeHeadingSource
	IDs, PrivateIDs             []string
	Private                     string
	OriginalSpan, ProjectedSpan graph.Span
	Ordinal                     int
	Valid                       bool
}

// Inline-code ownership can differ between the two grammars while each still
// accounts for every heading. Bind both whole readings, the complete allocation
// and the original byte before a missing check name can own the difference.
func agreementSeparateNamespaceHeadingReading(body string, f *agreementFailure, page *agreementHTML) agreementSeparateNamespaceHeadingSource {
	r := agreementSeparateNamespaceHeadingSource{Ordinal: -1}
	if f == nil || page == nil || f.Property != "P4" || f.Identity != "literal-heading-id" || f.Direction != "page-only" || f.Multiplicity != 1 || f.Tuple != (agreementCitation{}) || !f.PagePresent || f.JudgeAccepted || f.ExcerptFound || f.Cut != "" || strings.Contains(body, "q") {
		return r
	}
	r.Original = agreementSeparateNamespaceHeadingRead(body)
	a := &r.Original
	if !a.Valid || !slices.Equal(a.IDs, page.Headings) || a.Native.Names[f.Fragment] {
		return r
	}
	r.IDs, r.Native = a.IDs, a.Native
	for i, id := range r.IDs {
		if id == f.Fragment {
			if r.Ordinal >= 0 {
				return r
			}
			r.Ordinal = i
		}
	}
	if r.Ordinal < 0 || r.Ordinal >= len(a.Page.Headings) {
		return r
	}
	span := a.Page.Headings[r.Ordinal]
	if span.Start < 0 || span.Stop <= span.Start || span.Stop > len(a.Positions) {
		return r
	}
	found := -1
	for at := span.Start; at < span.Stop; at++ {
		if a.Projected[at] != 'A' {
			continue
		}
		protected := false
		for _, field := range a.Page.Fields {
			if field.Span.Start <= at && at < field.Span.Stop {
				protected = true
			}
		}
		for _, code := range a.Page.Code {
			if code.Start <= at && at < code.Stop {
				protected = true
			}
		}
		if !protected {
			found = at
			break
		}
	}
	if found < 0 {
		return r
	}
	r.ProjectedSpan = graph.Span{Start: found, Stop: found + 1}
	start := a.Positions[found]
	if start < 0 || start >= len(body) || body[start] != 'A' {
		return r
	}
	r.OriginalSpan = graph.Span{Start: start, Stop: start + 1}
	private := []byte(body)
	private[start] = 'q'
	r.Private = string(private)
	r.PrivateReading = agreementSeparateNamespaceHeadingRead(r.Private)
	b := &r.PrivateReading
	if !b.Valid || !slices.Equal(a.Positions, b.Positions) || !slices.Equal(a.Native.Check.Targets, b.Native.Check.Targets) {
		return r
	}
	expected := []byte(a.Projected)
	expected[found] = 'q'
	if string(expected) != b.Projected || !cmp.Equal(a.Page.Headings, b.Page.Headings) || !cmp.Equal(a.Page.Code, b.Page.Code) || !cmp.Equal(a.Page.Fields, b.Page.Fields) || len(a.Page.Bases) != len(b.Page.Bases) || len(a.Page.Checks) != len(b.Page.Checks) {
		return r
	}
	for i := range a.Page.Bases {
		if i == r.Ordinal {
			if a.Page.Bases[i] == b.Page.Bases[i] || a.Page.Checks[i] == b.Page.Checks[i] {
				return r
			}
		} else if a.Page.Bases[i] != b.Page.Bases[i] || a.Page.Checks[i] != b.Page.Checks[i] {
			return r
		}
	}
	r.PrivateIDs, r.PrivateNative = b.IDs, b.Native
	r.Valid = true
	return r
}
func agreementSeparateNamespaceHeadingEquation(ids []string, names map[string]bool, failures []agreementFailure) bool {
	expected := map[string]int{}
	for _, id := range ids {
		if !names[id] {
			f := agreementFailure{Property: "P4", Identity: "literal-heading-id", Fragment: id, Direction: "page-only", Multiplicity: 1, PagePresent: true}
			expected[agreementSignature(&f)]++
		}
	}
	actual := map[string]int{}
	for i := range failures {
		f := &failures[i]
		if f.Property == "P4" {
			actual[agreementSignature(f)]++
		}
	}
	return maps.Equal(expected, actual)
}
func agreementSeparateNamespaceHeadingProjection(source *agreementSeparateNamespaceHeadingSource, before, after []agreementFailure, page, privatePage *agreementHTML, diagnostics, privateDiagnostics []render.Diagnostic) bool {
	if source == nil || page == nil || privatePage == nil || !source.Valid || !slices.Equal(source.IDs, page.Headings) || !slices.Equal(source.PrivateIDs, privatePage.Headings) || !cmp.Equal(diagnostics, privateDiagnostics) || !agreementSeparateNamespaceHeadingEquation(source.IDs, source.Native.Names, before) || !agreementSeparateNamespaceHeadingEquation(source.PrivateIDs, source.PrivateNative.Names, after) {
		return false
	}
	a, b := *page, *privatePage
	a.Headings = nil
	b.Headings = nil
	if !cmp.Equal(a, b) {
		return false
	}
	original, private := map[string]int{}, map[string]int{}
	for i := range before {
		f := &before[i]
		if f.Property != "P4" {
			original[agreementSignature(f)]++
		}
	}
	for i := range after {
		f := &after[i]
		if f.Property != "P4" {
			private[agreementSignature(f)]++
		}
	}
	return maps.Equal(original, private)
}
func agreementSeparateNamespaceHeadingDifference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 {
		return "", "", ""
	}
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		if c.Body != r.Body || agreementSignature(f) != r.Selected {
			continue
		}
		if html != r.HTML || !cmp.Equal(*page, r.Page) || !cmp.Equal(diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), agreementMixedCurrent(r.Before)) {
			return "", "", ""
		}
		source := agreementSeparateNamespaceHeadingReading(c.Body, f, page)
		if !cmp.Equal(source, r.Source) || !agreementSeparateNamespaceHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
			return "", "", ""
		}
		return "debt", "#1011 stage 8", "judge"
	}
	return "", "", ""
}
func agreementSeparateNamespaceHeadingSelected(t *testing.T, r *agreementSeparateNamespaceHeadingDeclaration) agreementFailure {
	t.Helper()
	var selected agreementFailure
	seen := 0
	for i := range r.Before {
		f := &r.Before[i]
		if agreementSignature(f) == r.Selected {
			selected = *f
			seen++
		}
	}
	if seen != 1 {
		t.Fatal("caught: unique separate namespace heading declaration")
	}
	return selected
}
func TestAgreementSeparateNamespaceHeadingOwnedSource(t *testing.T) {
	rows := agreementSeparateNamespaceHeadingDeclarations()
	if len(rows) != 6 {
		t.Fatal("caught: complete separate namespace heading declaration set")
	}
	for i := range rows {
		r := &rows[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			selected := agreementSeparateNamespaceHeadingSelected(t, r)
			source := agreementSeparateNamespaceHeadingReading(r.Body, &selected, &r.Page)
			if !source.Valid || !cmp.Equal(source, r.Source) || source.Private != r.Private {
				t.Fatalf("caught: complete separate namespace heading physical source and whole namespace (-want +got):\n%s", cmp.Diff(r.Source, source))
			}
			span := source.OriginalSpan
			private := []byte(r.Body)
			if span.Start < 0 || span.Stop > len(private) || span.Stop <= span.Start {
				t.Fatal("caught: physical separate namespace heading interval")
			}
			copy(private[span.Start:span.Stop], strings.Repeat("q", span.Stop-span.Start))
			if string(private) != r.Private || source.Ordinal < 0 || source.IDs[source.Ordinal] != selected.Fragment || !agreementSeparateNamespaceHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: complete separate namespace heading signed source projection")
			}
		})
	}
}
func TestAgreementSeparateNamespaceHeadingOwnedPublic(t *testing.T) {
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			raw, page, before := agreementProseP0Failures(t, r.Body)
			pr, pp, after := agreementProseP0Failures(t, r.Private)
			if raw.HTML != r.HTML || pr.HTML != r.PrivateHTML || !cmp.Equal(page, r.Page) || !cmp.Equal(pp, r.PrivatePage) || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !cmp.Equal(pr.Diagnostics, r.PrivateDiagnostics) || !maps.Equal(agreementMixedCurrent(before), agreementMixedCurrent(r.Before)) || !maps.Equal(agreementMixedCurrent(after), agreementMixedCurrent(r.After)) || !agreementSeparateNamespaceHeadingProjection(&r.Source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics) {
				t.Fatal("caught: complete separate namespace heading public and diagnostic ledgers")
			}
			selected := agreementSeparateNamespaceHeadingSelected(t, r)
			k, a, w := agreementSeparateNamespaceHeadingDifference(agreementCase{Body: r.Body}, &selected, raw.HTML, &page, raw.Diagnostics, before)
			if k != "debt" || a != "#1011 stage 8" || w != "judge" {
				t.Fatal("caught: exact separate namespace heading authority and original source membership")
			}
		})
	}
}
func TestAgreementSeparateNamespaceHeadingOwnedRefusals(t *testing.T) {
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementSeparateNamespaceHeadingSelected(t, r)
			refuse := func(c agreementCase, x *agreementFailure, html string, page *agreementHTML, ds []render.Diagnostic, fs []agreementFailure) {
				t.Helper()
				k, a, w := agreementSeparateNamespaceHeadingDifference(c, x, html, page, ds, fs)
				if k != "" || a != "" || w != "" {
					t.Fatal("caught: separate namespace heading refuses changed complete source or context")
				}
			}
			for _, c := range []agreementCase{{Body: r.Body + "!"}, {Body: r.Body, Title: "outside"}, {Body: r.Body, Companions: capturedBodies{"outside.md": "outside"}}} {
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			c := agreementCase{Body: r.Body}
			refuse(c, nil, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML, nil, r.Diagnostics, r.Before)
			refuse(c, &f, r.HTML+"!", &r.Page, r.Diagnostics, r.Before)
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "outside" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				refuse(c, &x, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
			altered := r.Page
			altered.Headings = append(slices.Clone(r.Page.Headings), "outside")
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			altered = r.Page
			altered.Citations = append(slices.Clone(r.Page.Citations), agreementCitation{Target: "outside"})
			refuse(c, &f, r.HTML, &altered, r.Diagnostics, r.Before)
			ds := append(slices.Clone(r.Diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			refuse(c, &f, r.HTML, &r.Page, ds, r.Before)
			for j := range r.Before {
				fs := slices.Delete(slices.Clone(r.Before), j, j+1)
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, fs)
				if agreementSeparateNamespaceHeadingProjection(&r.Source, fs, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every original separate namespace heading receipt retained")
				}
			}
			for j := range r.After {
				fs := slices.Delete(slices.Clone(r.After), j, j+1)
				if agreementSeparateNamespaceHeadingProjection(&r.Source, r.Before, fs, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
					t.Fatal("caught: every private separate namespace heading receipt retained")
				}
			}
			source := r.Source
			source.IDs = append(slices.Clone(r.Source.IDs), "outside")
			if agreementSeparateNamespaceHeadingProjection(&source, r.Before, r.After, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics) {
				t.Fatal("caught: whole separate namespace heading source allocation retained")
			}
		})
	}
}
func TestAgreementSeparateNamespaceHeadingOwnedCensus(t *testing.T) {
	rows := agreementSeparateNamespaceHeadingProspects()
	if len(rows) != 319 {
		t.Fatal("caught: whole separate namespace heading prospect roster")
	}
	qualified := map[[3]string]bool{}
	for i := range rows {
		r := &rows[i]
		raw, page, before := agreementProseP0Failures(t, r.Body)
		var selected agreementFailure
		seen := 0
		for j := range before {
			f := &before[j]
			if agreementSignature(f) == r.Selected {
				selected = *f
				seen++
			}
		}
		if seen != 1 {
			t.Fatal("caught: every original separate namespace heading prospect exists")
		}
		source := agreementSeparateNamespaceHeadingReading(r.Body, &selected, &page)
		eligible := false
		if source.Valid {
			pr, pp, after := agreementProseP0Failures(t, source.Private)
			eligible = agreementSeparateNamespaceHeadingProjection(&source, before, after, &page, &pp, raw.Diagnostics, pr.Diagnostics)
		}
		if eligible != r.Eligible {
			t.Fatalf("caught: whole separate namespace heading eligibility and refusal set case=%s selected=%s got=%t want=%t", r.Case, r.Selected, eligible, r.Eligible)
		}
		if eligible {
			qualified[[3]string{r.Body, r.Case, r.Selected}] = true
		}
	}
	declared := map[[3]string]bool{}
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		declared[[3]string{r.Body, r.Case, r.Selected}] = true
	}
	if len(declared) != 6 || !maps.Equal(qualified, declared) {
		t.Fatal("caught: complete separate namespace heading eligible declaration set")
	}
}
func TestAgreementSeparateNamespaceHeadingOwnedProjectionRefusals(t *testing.T) {
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			reject := func(s *agreementSeparateNamespaceHeadingSource, page, privatePage *agreementHTML, ds, pds []render.Diagnostic) {
				t.Helper()
				if agreementSeparateNamespaceHeadingProjection(s, r.Before, r.After, page, privatePage, ds, pds) {
					t.Fatal("caught: separate namespace heading refuses changed whole projection")
				}
			}
			reject(nil, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, nil, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			reject(&r.Source, &r.Page, nil, r.Diagnostics, r.PrivateDiagnostics)
			s := r.Source
			s.Valid = false
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.IDs = append(slices.Clone(s.IDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.PrivateIDs = append(slices.Clone(s.PrivateIDs), "outside")
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			s = r.Source
			s.Native.Names = maps.Clone(s.Native.Names)
			f := agreementSeparateNamespaceHeadingSelected(t, r)
			s.Native.Names[f.Fragment] = true
			reject(&s, &r.Page, &r.PrivatePage, r.Diagnostics, r.PrivateDiagnostics)
			pp := r.PrivatePage
			pp.Headings = append(slices.Clone(pp.Headings), "outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Citations = append(slices.Clone(pp.Citations), agreementCitation{Target: "outside"})
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			pp = r.PrivatePage
			pp.Blocks = append(slices.Clone(pp.Blocks), "^outside")
			reject(&r.Source, &r.Page, &pp, r.Diagnostics, r.PrivateDiagnostics)
			ds := append(slices.Clone(r.PrivateDiagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "outside"})
			reject(&r.Source, &r.Page, &r.PrivatePage, r.Diagnostics, ds)
		})
	}
}
func TestAgreementSeparateNamespaceHeadingOwnedPhysicalRefusals(t *testing.T) {
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		t.Run(strconv.Itoa(i), func(t *testing.T) {
			f := agreementSeparateNamespaceHeadingSelected(t, r)
			if agreementSeparateNamespaceHeadingReading(r.Body, nil, &r.Page).Valid || agreementSeparateNamespaceHeadingReading(r.Body, &f, nil).Valid {
				t.Fatal("caught: separate namespace heading physical context")
			}
			changes := []func(*agreementFailure){func(f *agreementFailure) { f.Property = "P1" }, func(f *agreementFailure) { f.Identity = "outside" }, func(f *agreementFailure) { f.Fragment = "outside" }, func(f *agreementFailure) { f.Direction = "judge-only" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Tuple.SourceRole = "outside" }, func(f *agreementFailure) { f.Tuple.Target = "outside" }, func(f *agreementFailure) { f.Tuple.Section = "outside" }, func(f *agreementFailure) { f.Tuple.State = "outside" }, func(f *agreementFailure) { f.PagePresent = false }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "outside" }}
			for _, change := range changes {
				x := f
				change(&x)
				if agreementSeparateNamespaceHeadingReading(r.Body, &x, &r.Page).Valid {
					t.Fatal("caught: separate namespace heading refuses another physical property or signature")
				}
			}
			changed := r.Page
			changed.Headings = append(slices.Clone(changed.Headings), "outside")
			if agreementSeparateNamespaceHeadingReading(r.Body, &f, &changed).Valid {
				t.Fatal("caught: separate namespace heading refuses altered physical allocation")
			}
		})
	}
}

func TestAgreementSeparateNamespaceHeadingOwnedReaderRefusals(t *testing.T) {
	equal := "## A\n## A\n"
	strict := agreementNeutralHeadingRead(equal)
	if !strict.Valid || !cmp.Equal(strict.Plain, strict.Page) {
		t.Fatal("caught: ordinary equal-grammar control exists")
	}
	if agreementSeparateNamespaceHeadingRead(equal).Valid {
		t.Fatal("caught: separate namespace owner refuses equal grammar readings")
	}
	invalid := string([]byte{0xff})
	if agreementSeparateNamespaceHeadingRead(invalid).Valid {
		t.Fatal("caught: separate namespace owner refuses invalid source bytes")
	}
	for i := range agreementSeparateNamespaceHeadingDeclarations() {
		r := &agreementSeparateNamespaceHeadingDeclarations()[i]
		if cmp.Equal(r.Source.Original.Plain, r.Source.Original.Page) || cmp.Equal(r.Source.PrivateReading.Plain, r.Source.PrivateReading.Page) {
			t.Fatal("caught: every original and private independent grammar relationship")
		}
	}
}
